def f(I):
    I=[list(map(int,r)) for r in I]; H=len(I);W=len(I[0])
    pts=[(i,j,I[i][j]) for i in range(H) for j in range(W) if I[i][j] not in (0,2)]
    b=[(i,j) for i in range(H) for j in range(W) if I[i][j]==2]
    ci=sum(p[0] for p in b)/len(b); cj=sum(p[1] for p in b)/len(b)
    # classify: main diag if (i-ci)(j-cj)>0 else anti
    mains=[];antis=[]
    for p in pts:
        v=(p[0]-ci)*(p[1]-cj)
        if v>0: mains.append(p)
        elif v<0: antis.append(p)
        else: pass  # on vertical/horizontal diag through center (can't happen)
    out=[r[:] for r in I]
    def ext(i,j,d,c):
        while True:
            i+=d[0]; j+=d[1]
            if not(0<=i<H and 0<=j<W) or I[i][j]==2: break
            out[i][j]=c
    U=[p for p in mains if p[0]<ci]; D=[p for p in mains if p[0]>ci]
    Up=[p for p in antis if p[0]+p[1]<ci+cj]; Dn=[p for p in antis if p[0]+p[1]>ci+cj]
    ext(U[0][0],U[0][1],(-1,-1),Dn[0][2]); ext(D[0][0],D[0][1],(1,1),Up[0][2])
    ext(Up[0][0],Up[0][1],(-1,1),U[0][2]); ext(Dn[0][0],Dn[0][1],(1,-1),D[0][2])
    return out
