        cy=(r0+r1)/2; cx=(c0+c1)/2
        for cn,(dy,dx) in corners.items():
            src=rotCW((dy,dx))
            cand=[c_ for mi,mj,c_ in markers
                  if ((mi-cy>0)==(src[0]>0) and (mi-cy<0)==(src[0]<0) and abs(mi-cy)<=0.5) and
                  ((mj-cx>0)==(src[1]>0) and (mj-cx<0)==(src[1]<0) and abs(mj-cx)<=0.5)]
            if not cand: continue
            mc=cand[0]
            start = {'tl':(r0-1,c0-1),'tr':(r0-1,c1+1),'bl':(r1+1,c0-1),'br':(r1+1,c1+1)}[cn]
            ti,tj=start
            # paint start too if it's a marker (it will get repainted by this ray later via cross-color anyway)
            if 0<=start[0]<H and 0<=start[1]<W and not(start[0],start[1]) in twos:
                out[start[0]][start[1]]=mc
            step=1
            while True:
                ti+=dy; tj+=dx
                if not(0<=ti<H and 0<=tj<W) or I[ti,tj]==2: break
